script:
(function () {
  'use strict';
  // Civilian salary that matches military take-home pay (tax year 2026, annual figures).
  //   Military taxable pay = (basic pay + taxable special pay) x 12. BAH and BAS are tax-free
  //   allowances (IRC 134; 26 CFR 1.134-1): no federal income tax and no FICA.
  //   Military take-home = basic + special + BAH + BAS - federal tax - FICA on taxable pay
  //                        - state rate x taxable pay
  //   Civilian take-home(S) = S - federal tax(S) - FICA(S) - civilian state rate x S
  //   The civilian salary S is solved by bisection so civilian take-home = military take-home.
  // Pay tables are not built in: the user enters their own basic pay, BAH and BAS.
  // Verified (Node, scratch tests): basic $3,800, BAH $1,800, BAS $480 a month, single, 0% state
  // on military pay, 4% civilian: military take-home $66,179.60 (tax $3,292, FICA $3,488.40);
  // closed form in the 22% band: S = (66,179.60 - 8,830) / 0.6635 = $86,434.97 -> $86,435.
  // With no allowances and equal state rates the salary equals basic pay ($45,600).
  // ---- 2026 FEDERAL CONSTANTS (tax year 2026) -------------------------------------------
  // Copied from take-home-paycheck-calculator (verified there). Brackets and standard
  // deductions: IRS Rev. Proc. 2025-32 (as amended by P.L. 119-21). Child tax credit $2,200 and
  // $500 other-dependent credit: IRC 24(h) as amended by P.L. 119-21. Social Security wage base
  // and rates: SSA 2026 fact sheet. Medicare and 0.9% Additional Medicare: IRC 3101(b).
  var TAX_YEAR = 2026;
  var BRACKETS = { // upper limit of each band; rates 10, 12, 22, 24, 32, 35, 37%
    single: [12400, 50400, 105700, 201775, 256225, 640600],
    mfj:    [24800, 100800, 211400, 403550, 512450, 768700],
    mfs:    [12400, 50400, 105700, 201775, 256225, 384350],
    hoh:    [17700, 67450, 105700, 201750, 256200, 640600]
  };
  var RATES = [0.10, 0.12, 0.22, 0.24, 0.32, 0.35, 0.37];
  var STANDARD_DEDUCTION = { single: 16100, mfj: 32200, mfs: 16100, hoh: 24150 };
  var CHILD_CREDIT = 2200;               // per child under 17
  var OTHER_DEPENDENT_CREDIT = 500;
  var CREDIT_PHASEOUT_START = { single: 200000, hoh: 200000, mfs: 200000, mfj: 400000 }; // $50 per $1,000
  var SS_RATE = 0.062, SS_WAGE_BASE = 184500;
  var MEDICARE_RATE = 0.0145, ADDL_MEDICARE_RATE = 0.009, ADDL_MEDICARE_WITHHOLD_START = 200000;
  // ---------------------------------------------------------------------------------------

  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var cents = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2, minimumFractionDigits: 2 });

  function num(id) {
    var el = document.getElementById(id);
    if (!el) return NaN;
    var v = parseFloat(el.value);
    return isNaN(v) ? NaN : v;
  }

  function bracketTax(taxable, limits) {
    var tax = 0, lower = 0, marginal = 0;
    for (var i = 0; i < RATES.length; i++) {
      var upper = i < limits.length ? limits[i] : Infinity;
      if (taxable > lower) {
        tax += (Math.min(taxable, upper) - lower) * RATES[i];
        marginal = RATES[i];
      }
      lower = upper;
    }
    return { tax: tax, marginal: marginal };
  }

  // Annual federal income tax: AGI - standard deduction - extra deductions, brackets, then
  // non-refundable child / dependent credits (refundable part of the child credit not modelled).
  function federalTax(agi, status, kids, otherDeps, extraDeduction) {
    var taxable = Math.max(0, agi - STANDARD_DEDUCTION[status] - (extraDeduction || 0));
    var bt = bracketTax(taxable, BRACKETS[status]);
    var credits = kids * CHILD_CREDIT + otherDeps * OTHER_DEPENDENT_CREDIT;
    var over = Math.max(0, agi - CREDIT_PHASEOUT_START[status]);
    credits = Math.max(0, credits - Math.ceil(over / 1000) * 50);
    return { taxable: taxable, tax: Math.max(0, bt.tax - credits), marginal: bt.marginal };
  }

  function ficaTax(wages) {
    var ss = SS_RATE * Math.min(wages, SS_WAGE_BASE);
    var medicare = MEDICARE_RATE * wages + ADDL_MEDICARE_RATE * Math.max(0, wages - ADDL_MEDICARE_WITHHOLD_START);
    return { ss: ss, medicare: medicare };
  }

  function takeHome(taxablePay, taxFreePay, stateRate, o) {
    var fed = federalTax(taxablePay, o.status, o.kids, o.otherDeps, 0);
    var f = ficaTax(taxablePay);
    var state = stateRate / 100 * taxablePay;
    return { gross: taxablePay + taxFreePay, taxable: taxablePay, federal: fed.tax, ss: f.ss,
             medicare: f.medicare, state: state,
             net: taxablePay + taxFreePay - fed.tax - f.ss - f.medicare - state };
  }

  function solveSalary(targetNet, o) {
    var lo = 0, hi = Math.max(1000, targetNet * 2), guard = 0;
    while (takeHome(hi, 0, o.stateCiv, o).net < targetNet) {
      hi *= 2;
      if (++guard > 60) return null;
    }
    for (var i = 0; i < 200 && hi - lo > 1e-6; i++) {
      var mid = (lo + hi) / 2;
      if (takeHome(mid, 0, o.stateCiv, o).net >= targetNet) hi = mid; else lo = mid;
    }
    return hi;
  }

  function compute(o) {
    var mil = takeHome((o.basic + o.special) * 12, (o.bah + o.bas) * 12, o.stateMil, o);
    var salary = mil.net > 0 ? solveSalary(mil.net, o) : 0;
    if (salary === null) return null;
    var civ = takeHome(salary, 0, o.stateCiv, o);
    return { mil: mil, civ: civ, salary: salary };
  }

  function setText(id, text) { var el = document.getElementById(id); if (el) el.textContent = text; }

  function update() {
    var o = {
      basic: num('mpBasic'), bah: num('mpBah'), bas: num('mpBas'), special: num('mpSpecial'),
      status: document.getElementById('mpStatus').value, kids: Math.round(num('mpKids')),
      otherDeps: Math.round(num('mpOtherDeps')), stateMil: num('mpStateMil'), stateCiv: num('mpStateCiv')
    };
    if (!BRACKETS[o.status]) o.status = 'single';
    var error = document.getElementById('mpError');
    var nums = [o.basic, o.bah, o.bas, o.special, o.kids, o.otherDeps, o.stateMil, o.stateCiv];
    var bad = nums.some(function (v) { return !isFinite(v) || v < 0; }) ||
              o.basic + o.bah + o.bas + o.special <= 0 || o.basic + o.bah + o.bas + o.special > 1e6 ||
              o.stateMil > 20 || o.stateCiv > 20 || o.kids > 20 || o.otherDeps > 20;
    var r = bad ? null : compute(o);
    if (!bad && r === null) bad = true;
    error.hidden = !bad;
    if (bad) {
      error.textContent = 'Enter non-negative monthly amounts (at least one above zero) and state rates from 0 to 20%.';
      return;
    }

    setText('mpSalary', money.format(r.salary));
    setText('mpMilNet', money.format(r.mil.net));
    setText('mpAdvantage', money.format(Math.max(0, r.salary - r.mil.gross)));
    setText('mpMilGross', money.format(r.mil.gross));
    setText('mpTaxFree', money.format((o.bah + o.bas) * 12));
    setText('mpMonthlyNet', cents.format(r.mil.net / 12));
    setText('mpHourly', cents.format(r.salary / 2080));

    var rows = [
      ['Total pay', r.mil.gross, r.civ.gross],
      ['Tax-free allowances (BAH, BAS)', (o.bah + o.bas) * 12, 0],
      ['Taxable pay', r.mil.taxable, r.civ.taxable],
      ['Federal income tax', -r.mil.federal, -r.civ.federal],
      ['Social Security (6.2%)', -r.mil.ss, -r.civ.ss],
      ['Medicare', -r.mil.medicare, -r.civ.medicare],
      ['State and local income tax', -r.mil.state, -r.civ.state],
      ['Take-home pay', r.mil.net, r.civ.net]
    ];
    document.getElementById('mpCompare').innerHTML = rows.map(function (row, i) {
      var cell = function (v) { if (Math.abs(v) < 0.5) return money.format(0); return v < 0 ? '−' + money.format(-v) : money.format(v); };
      var last = i === rows.length - 1;
      return '<tr><th scope="row">' + (last ? '<strong>' + row[0] + '</strong>' : row[0]) + '</th><td>' +
             cell(row[1]) + '</td><td>' + cell(row[2]) + '</td></tr>';
    }).join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('mpForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
